403	static void bt_acl_recv(struct bt_conn *conn, struct net_buf *buf, uint8_t flags)
404	{
405		uint16_t acl_total_len;
406	
407		bt_acl_set_ncp_sent(buf, false);
408	
409		/* Check packet boundary flags */
410		switch (flags) {
411		case BT_ACL_START:
412			if (conn->rx) {
413				LOG_ERR("Unexpected first L2CAP frame");
414				bt_conn_reset_rx_state(conn);
415			}
416	
417			LOG_DBG("First, len %u final %u", buf->len,
418				(buf->len < sizeof(uint16_t)) ? 0 : sys_get_le16(buf->data));
419	
420			conn->rx = net_buf_ref(buf);
421			break;
422		case BT_ACL_CONT:
423			if (!conn->rx) {
424				LOG_ERR("Unexpected L2CAP continuation");
425				bt_conn_reset_rx_state(conn);
426				net_buf_unref(buf);
427				return;
428			}
429	
430			if (!buf->len) {
431				LOG_DBG("Empty ACL_CONT");
432				net_buf_unref(buf);
433				return;
434			}
435	
436			if (buf->len > net_buf_tailroom(conn->rx)) {
437				LOG_ERR("Not enough buffer space for L2CAP data");
438	
439				/* Frame is not complete but we still pass it to L2CAP
440				 * so that it may handle error on protocol level
441				 * eg disconnect channel.
442				 */
443				bt_l2cap_recv(conn, conn->rx, false);
444				conn->rx = NULL;
445				net_buf_unref(buf);
446				return;
447			}
448	
449			net_buf_add_mem(conn->rx, buf->data, buf->len);
450			break;
451		default:
452			/* BT_ACL_START_NO_FLUSH and BT_ACL_COMPLETE are not allowed on
453			 * LE-U from Controller to Host.
454			 * Only BT_ACL_POINT_TO_POINT is supported.
455			 */
456			LOG_ERR("Unexpected ACL flags (0x%02x)", flags);
457			bt_conn_reset_rx_state(conn);
458			net_buf_unref(buf);
459			return;
460		}
461	
462		if (conn->rx->len < sizeof(uint16_t)) {
463			/* Still not enough data received to retrieve the L2CAP header
464			 * length field.
465			 */
466			bt_send_one_host_num_completed_packets(conn->hdev, conn->handle);
467			bt_acl_set_ncp_sent(buf, true);
468			net_buf_unref(buf);
469	
470			return;
471		}
472	
473		acl_total_len = sys_get_le16(conn->rx->data) + sizeof(struct bt_l2cap_hdr);
474	
475		if (conn->rx->len < acl_total_len) {
476			/* L2CAP frame not complete. */
477			bt_send_one_host_num_completed_packets(conn->hdev, conn->handle);
478			bt_acl_set_ncp_sent(buf, true);
479			net_buf_unref(buf);
480	
481			return;
482		}
483	
484		net_buf_unref(buf);
485	
486		if (conn->rx->len > acl_total_len) {
487			LOG_ERR("ACL len mismatch (%u > %u)", conn->rx->len, acl_total_len);
488			bt_conn_reset_rx_state(conn);
489			return;
490		}
491	
492		/* L2CAP frame complete. */
493		buf = conn->rx;
494		conn->rx = NULL;
495	
496		__ASSERT(buf->ref == 1, "buf->ref %d", buf->ref);
497	
498		LOG_DBG("Successfully parsed %u byte L2CAP packet", buf->len);
499		bt_l2cap_recv(conn, buf, true);
500	}
